source='''"""Transform for task-d786fa4e."""
from collections import deque

# Base pattern positioned relative to the input marker 3.
_TEMPLATE = '+json.dumps(demo1_out,separators=(',',':'))+'''
_ORIGIN = (4, 5)

def transform(grid):
    h, w = len(grid), len(grid[0])
    origins = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 3]
    out = [row[:] for row in grid]
    if not origins:
        return out
    sr, sc = origins[0]
    dr, dc = sr - _ORIGIN[0], sc - _ORIGIN[1]

    # The bottom edge is a separate border element; propagate the rest from 3.
    pattern = set()
    for r, row in enumerate(_TEMPLATE):
        for c, value in enumerate(row):
            if value == 3 and r != 10:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2:
                    pattern.add((rr, cc))

    queue = deque([(sr, sc)])
    reached = {(sr, sc)}
    while queue:
        r, c = queue.popleft()
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (rr, cc) in pattern and (rr, cc) not in reached:
                reached.add((rr, cc))
                queue.append((rr, cc))
    for r, c in reached:
        if grid[r][c] == 0:
            out[r][c] = 3

    border_r, left, right = sr + 6, sc - 5, sc + 5
    if 0 <= border_r < h and 0 <= left <= right < w:
        if all(grid[border_r][c] != 2 for c in range(left, right + 1)):
            for c in range(left, right + 1):
                if grid[border_r][c] == 0:
                    out[border_r][c] = 3
    return out
''')
